// Milanuncios tiene rate-limit anti-bot (PerimeterX): cupo ~9-10 peticiones/ventana.
// Run limpio: 1 marca/noche (1 pág-1 + hasta 6 loop = ~7 peticiones, bajo el cupo).
// Rotación por día del año → ciclo completo ~68 noches.
const brands = ["peugeot","mercedes-benz","kia","citroen","volkswagen","ford","opel","renault","audi","seat","bmw","toyota","nissan","hyundai","fiat","mg","skoda","jeep","volvo","mazda","ds","cupra","dacia","mini","mitsubishi","lexus","land-rover","honda","suzuki","alfa-romeo","ssangyong","byd","porsche","jaguar","subaru","smart","dfsk","tesla","iveco","abarth","leapmotor","chevrolet","maserati","lancia","maxus","infiniti","ferrari","bentley","geely","chrysler","polestar","dodge","alpine","aston-martin","saab","dongfeng","ineos","mahindra","rover","cadillac","isuzu","lamborghini","lotus","hummer","maybach","omoda","jaecoo","tata","daewoo"];
const PER = 1;
const now = new Date();
const doy = Math.floor((Date.now() - Date.UTC(now.getUTCFullYear(), 0, 0)) / 86400000);
const groups = Math.ceil(brands.length / PER);
const g = doy % groups;
const mine = brands.slice(g * PER, g * PER + PER);
const out = [];
for (const b of mine) out.push({ json: { url: 'https://www.milanuncios.com/' + b + '-de-segunda-mano/' } });
return out;

// De la página 1 de cada marca: leer pagination.totalPages → generar ?pagina=N (tope CAP).
const inputs = $input.all();
const CAP = 6;
const out = [];
let sawBlock = false;
for (const inp of inputs) {
  const html = typeof inp.json === 'string' ? inp.json : String(inp.json.data || inp.json.body || '');
  if (/Pardon Our Interruption/i.test(html)) { sawBlock = true; continue; }
  let i = html.indexOf('window.__INITIAL_PROPS__');
  if (i < 0) continue;
  i = html.indexOf('"', i);
  let j = i + 1, esc = false, str = '';
  for (; j < html.length; j++) {
    const c = html[j];
    if (esc) { str += c; esc = false; }
    else if (c === '\\') { str += c; esc = true; }
    else if (c === '"') break;
    else str += c;
  }
  let pp;
  try { pp = JSON.parse(JSON.parse('"' + str + '"')); } catch (e) { continue; }
  const pag = pp.adListPagination;
  if (!pag || !pag.pagination) continue;
  const ads = (pag.adList && pag.adList.ads) || [];
  const catSlug = ads[0] && ads[0].category && ads[0].category.slug;
  if (!catSlug) continue;
  const baseUrl = 'https://www.milanuncios.com/' + catSlug + '/';
  const total = pag.pagination.totalPages || 1;
  const pages = Math.min(total, CAP);
  for (let p = 1; p <= pages; p++) out.push({ json: { url: baseUrl + '?pagina=' + p } });
}
if (out.length === 0) throw new Error('Milanuncios: 0 páginas generadas' + (sawBlock ? ' (bloqueo PerimeterX detectado en página 1)' : ''));
return out;

// Milanuncios - transform: HTML -> window.__INITIAL_PROPS__ (string JSON) ->
// adListPagination.adList.ads -> UPSERT moveadvisor_market_offers.
//
// Milanuncios bloquea por comportamiento, asi que cada pagina que se consigue
// traer hay que exprimirla. De ahi el reparto:
//
//   - Se guarda TODO lo que trae la pagina, incluida la descripcion, que va a
//     moveadvisor_offer_texts. Es lo unico que ocurre una sola vez: si no se
//     guarda ahora, para volver a verla hay que esperar 68 dias.
//   - Se deduce aqui lo barato y seguro -potencia y cambio del texto- para que
//     la oferta ya entre util desde el primer momento.
//   - Y lo que vale igual en los once portales -etiqueta de la DGT, cilindrada,
//     traccion- no se toca: de eso se encarga universal-derivar, para que la
//     regla viva en un sitio y no en once.

const httpOut = $input.item.json;
const html = typeof httpOut === 'string' ? httpOut : String(httpOut.data || httpOut.body || '');

// Rate-limit anti-bot: si llega la pagina de bloqueo, PARAR el run. Seguir
// pidiendo alarga el bloqueo, y llega con un HTTP 200, no con un error.
if (/Pardon Our Interruption/i.test(html)) {
  throw new Error('Milanuncios bloqueado — run detenido para no alargar el bloqueo');
}

// --- extraer window.__INITIAL_PROPS__ (es un string JSON escapado) ---
let ads = [];
try {
  let i = html.indexOf('window.__INITIAL_PROPS__');
  if (i >= 0) {
    i = html.indexOf('"', i);
    let j = i + 1, esc = false, out = '';
    for (; j < html.length; j++) {
      const c = html[j];
      if (esc) { out += c; esc = false; }
      else if (c === '\\') { out += c; esc = true; }
      else if (c === '"') break;
      else out += c;
    }
    const pp = JSON.parse(JSON.parse('"' + out + '"'));
    ads = (pp.adListPagination && pp.adListPagination.adList && pp.adListPagination.adList.ads) || [];
  }
} catch (e) { ads = []; }
if (!ads.length) return [{ json: { sql: null, count: 0 } }];

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return isNaN(v) ? 'NULL' : String(v);
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function cleanBrand(s) {
  s = String(s || '').replace(/-/g, ' ').replace(/\s+/g, ' ').trim();
  return s.replace(/\b\w/g, function (c) { return c.toUpperCase(); });
}
function normFuel(s) {
  s = String(s || '').toLowerCase();
  const ench = (s.indexOf('enchufable') !== -1 || s.indexOf('plug') !== -1) && s.indexOf('no enchufable') === -1;
  if (s.indexOf('diesel') !== -1 || s.indexOf('diésel') !== -1 || s.indexOf('gasoil') !== -1 || s.indexOf('gasóleo') !== -1) return 'Diesel';
  if (s.indexOf('híbrido') !== -1 || s.indexOf('hibrido') !== -1 || s.indexOf('hybrid') !== -1) return ench ? 'Híbrido enchufable' : 'Híbrido';
  if (s.indexOf('eléctric') !== -1 || s.indexOf('electric') !== -1) return 'Eléctrico';
  if (s.indexOf('gasolina') !== -1) return 'Gasolina';
  if (s.indexOf('glp') !== -1 || s.indexOf('gnc') !== -1 || s.indexOf('gas') !== -1) return 'Gas';
  return '';
}
function digits(s) { const m = String(s || '').replace(/\./g, '').match(/\d+/); return m ? parseInt(m[0], 10) : null; }
function tag(a, type) { const t = (a.tags || []).find(function (x) { return x && x.type === type; }); return t ? t.text : ''; }

// Las fechas de Milanuncios son ISO ('2026-07-13T11:13:43Z'), no epoch.
function fecha(s) {
  if (!s) return 'NULL';
  const t = Date.parse(s);
  if (!t || isNaN(t)) return 'NULL';
  return "'" + new Date(t).toISOString() + "'::timestamptz";
}

// 'warrantyPeriod' llega como texto: '12 meses (1 año)', '2 años', 'Sin garantia'.
function meses(s) {
  const t = String(s || '').toLowerCase();
  if (!t || t.indexOf('sin ') === 0) return null;
  const m = t.match(/(\d+)\s*mes/);
  if (m) return parseInt(m[1], 10);
  const a = t.match(/(\d+)\s*a[nñ]o/);
  if (a) return parseInt(a[1], 10) * 12;
  return null;
}

const rows = [];
const textos = [];
const seen = {};
for (const a of ads) {
  if (!a || !a.id) continue;
  const price = a.price && a.price.cashPrice && a.price.cashPrice.value != null ? a.price.cashPrice.value : null;
  if (price === null) continue; // precio obligatorio

  const id = 'mil_' + a.id;
  if (seen[id]) continue; // Milanuncios repite los destacados en la misma pagina
  seen[id] = 1;
  const brand = cleanBrand(a.category && a.category.name);
  const title = String(a.title || '').replace(/\s+/g, ' ').trim();
  // modelo/version: quitar la marca del principio del titulo
  let rest = title;
  const bl = (a.category && a.category.name ? a.category.name.replace(/-/g, ' ') : '').toLowerCase();
  if (bl && title.toLowerCase().indexOf(bl) === 0) rest = title.slice(bl.length).trim();
  else { const bw = (brand.split(' ')[0] || '').toLowerCase(); if (bw && title.toLowerCase().indexOf(bw) === 0) rest = title.slice(bw.length).trim(); }
  const sp = rest.indexOf(' ');
  const model = sp === -1 ? rest : rest.slice(0, sp);
  const version = sp === -1 ? '' : rest.slice(sp + 1).trim();

  const year = digits(tag(a, 'año'));
  const mileage = digits(tag(a, 'kilómetros'));
  const fuel = normFuel(tag(a, 'combustible'));
  // Ojo: las etiquetas de Milanuncios son SOLO kilometros, año y combustible.
  // Antes se leia tag(a,'cambio'), que no existe, y por eso transmission llevaba
  // meses al 3%: no fallaba, simplemente no habia nada que leer. El cambio sale
  // ahora del texto, y de eso se encarga el enriquecedor.

  const prov = (a.province && a.province.name) || (a.location && a.location.province && a.location.province.name) || '';
  const city = (a.location && a.location.city && a.location.city.name) || (a.city && a.city.name) || '';
  const sellerType = a.sellerType === 'private' ? 'particular' : 'profesional';
  const dealerName = sellerType === 'profesional' ? String(a.seoTitle || '') : '';

  // Las imagenes vienen sin protocolo NI regla de tamaño; sin '?rule=hwNNN_QQ' dan 404.
  // Tope 30 y no 15: en Wallapop medimos que con 15 se recortaba el 59% de los
  // anuncios y se guardaba solo el 64% de las fotos.
  const imgs = (Array.isArray(a.images) ? a.images : [])
    .map(function (u) { return u ? ('https://' + String(u).replace(/^https?:\/\//, '') + '?rule=hw396_70') : null; })
    .filter(Boolean).slice(0, 30);
  const imageUrl = imgs[0] || '';
  const imagesJson = JSON.stringify(imgs).replace(/'/g, "''");
  const url = a.url ? ('https://www.milanuncios.com' + a.url) : '';

  // La descripcion es la mina de este portal: 1.296 caracteres de media, en el
  // 100% de los anuncios, y es el UNICO sitio donde estan el color y buena parte
  // del cambio y la carroceria, porque las fichas de detalle estan bloqueadas.
  //
  // Va a moveadvisor_offer_texts, no a raw_payload: esa columna la vacia el
  // trigger trg_drop_raw_payload, puesto a proposito despues de que Flexicar
  // metiera ahi el JSON entero del vehiculo y el SQL se fuera a 285 KB por
  // pagina hasta dejar al runner sin memoria.
  const descripcion = String(a.description || '');
  const texto = title + ' ' + version + ' ' + descripcion;

  // Potencia: en el titulo suele venir como '88kW 120CV'. Se prefiere el CV
  // explicito y, si solo hay kW, se convierte. Medido sobre las 5.484 guardadas,
  // el 37% lleva potencia en el titulo; hoy la columna esta al 0%.
  let cv = null, kw = null;
  { const m = texto.match(/(\d{2,4})\s*cv\b/i); if (m) cv = parseInt(m[1], 10); }
  { const m = texto.match(/(\d{2,3})\s*kw\b/i); if (m) kw = parseInt(m[1], 10); }
  if (cv == null && kw != null) cv = Math.round(kw * 1.35962);
  if (kw == null && cv != null) kw = Math.round(cv / 1.35962);
  if (cv != null && (cv < 20 || cv > 1500)) { cv = null; kw = null; }

  // Cambio: sale de la descripcion en el 48% de los anuncios.
  let transmission = '';
  { const m = texto.match(/\b(autom[aá]tic\w*|manual|dsg|s.?tronic|tiptronic|cvt|edc|dct|pdk|steptronic)\b/i);
    if (m) transmission = /manual/i.test(m[1]) ? 'Manual' : 'Automatica'; }

  // Un anuncio reservado no esta a la venta aunque siga publicado.
  const reservado = a.isReserved === true;

  const garantia = meses(a.warrantyPeriod);

  const row = '(' +
    esc(id) + ", 'milanuncios', " + esc(url) + ', ' + esc(title) + ', ' + esc(brand) + ', ' + esc(model) + ', ' + esc(version) + ', ' +
    (year || 'NULL') + ', ' + (mileage != null ? mileage : 'NULL') + ', ' + price + ', ' +
    esc(fuel) + ', ' +
    esc(imageUrl) + ", '" + imagesJson + "', " + esc(dealerName) + ', ' +
    esc(city) + ', ' + esc(prov) + ', ' + esc(prov) + ', ' +
    "'" + sellerType + "', 'compra', " +
    (cv != null ? cv : 'NULL') + ', ' + (kw != null ? kw : 'NULL') + ', ' +
    esc(transmission) + ', ' +
    fecha(a.publishDate) + ', ' + fecha(a.updateDate) + ', ' +
    (garantia != null ? garantia : 'NULL') + ', ' +
    (reservado ? 'FALSE' : 'TRUE') +
    ', NOW(), NOW(), NOW(), NOW()' +
  ')';
  rows.push(row);

  // La descripcion va a su tabla, moveadvisor_offer_texts, no a la de ofertas.
  // Ahi es donde estan el color y buena parte del cambio y la carroceria, y
  // guardarla es lo que permite al enriquecedor releerla cuando mejoren las
  // expresiones sin volver a pedirle una pagina a Milanuncios -que con una marca
  // por noche son 68 dias de espera.
  if (descripcion) textos.push('(' + esc(id) + ", 'milanuncios', " + esc(descripcion.slice(0, 8000)) + ', NOW())');
}
if (!rows.length) return [{ json: { sql: null, count: 0 } }];

const cols = 'id, portal, url, title, brand, model, version, year, mileage, price, fuel, ' +
  'image_url, images, dealer_name, city, province, location, seller_type, listing_type, ' +
  'power_cv, power_kw, transmission, listed_at, source_updated_at, warranty_months, is_active, ' +
  'first_seen_at, scraped_at, last_seen_at, last_checked_at';

const onConflict = 'ON CONFLICT (id) DO UPDATE SET ' +
  'url = EXCLUDED.url, title = EXCLUDED.title, price = EXCLUDED.price, mileage = EXCLUDED.mileage, ' +
  'year = COALESCE(EXCLUDED.year, moveadvisor_market_offers.year), ' +
  'fuel = EXCLUDED.fuel, ' +
  "image_url = COALESCE(NULLIF(EXCLUDED.image_url,''), moveadvisor_market_offers.image_url), " +
  "images = COALESCE(NULLIF(EXCLUDED.images,''), moveadvisor_market_offers.images), " +
  // Lo sacado del texto solo rellena huecos: si ya hay un valor, se respeta.
  // Puede haberlo puesto una persona, o una version mejor de estas expresiones.
  'power_cv = COALESCE(moveadvisor_market_offers.power_cv, EXCLUDED.power_cv), ' +
  'power_kw = COALESCE(moveadvisor_market_offers.power_kw, EXCLUDED.power_kw), ' +
  "transmission = COALESCE(NULLIF(moveadvisor_market_offers.transmission,''), EXCLUDED.transmission), " +
  // La fecha de publicacion es la primera que vimos: no se pisa nunca.
  'listed_at = COALESCE(moveadvisor_market_offers.listed_at, EXCLUDED.listed_at), ' +
  'source_updated_at = EXCLUDED.source_updated_at, ' +
  'warranty_months = COALESCE(EXCLUDED.warranty_months, moveadvisor_market_offers.warranty_months), ' +
  // Un vendedor no deja de ser concesionario porque en esta pasada se le viera
  // un coche suelto: el tipo solo sube, nunca baja.
  "seller_type = CASE WHEN EXCLUDED.seller_type = 'profesional' THEN 'profesional' ELSE moveadvisor_market_offers.seller_type END, " +
  // Verlo en el listado es la mejor prueba de vida que hay en este portal: las
  // fichas de detalle estan bloqueadas, asi que el verificador no puede
  // preguntar una por una. Si esta aqui, esta vivo.
  'is_active = EXCLUDED.is_active, ' +
  'last_checked_at = NOW(), ' +
  'last_seen_at = NOW(), updated_at = NOW()';

let sql = 'INSERT INTO moveadvisor_market_offers (' + cols + ') VALUES ' + rows.join(', ') + ' ' + onConflict;

// Segunda sentencia, en la misma llamada: el nodo de Postgres las ejecuta las
// dos. Se refresca la descripcion en cada pasada porque el vendedor la edita.
if (textos.length) {
  sql += '; INSERT INTO moveadvisor_offer_texts (offer_id, portal, descripcion, capturado_en) VALUES ' +
    textos.join(', ') +
    ' ON CONFLICT (offer_id) DO UPDATE SET descripcion = EXCLUDED.descripcion, capturado_en = NOW()';
}

return [{ json: { sql: sql, count: rows.length, textos: textos.length } }];
